"""Plain-text absence notices for parents."""

from typing import Iterable

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed


def _check_owner(student: Student, marks: list) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )


def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice text listing the absent days, oldest first."""
    marks = list(marks)
    _check_owner(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError("no absences to report")
    return _compose(student, missed)


def _compose(student: Student, missed: list) -> str:
    dates = "\n".join(f"- {stamp}" for stamp in missed)
    return (
        f"{student.first_name} {student.last_name} "
        f"missed {len(missed)} day(s):\n{dates}"
    )
